# D3.js v6 Force Simulation Bubble Chart

## Overview
D3's force simulation enables creating bubble charts where elements are positioned using physics-based simulations. This is ideal for clustered bubble charts where bubbles group by category.

## Setup
Include D3.js v6:
```html
<script src="js/d3.v6.min.js"></script>
```

## Key Concepts

### Force Simulation
```javascript
const simulation = d3.forceSimulation(nodes)
  .force("charge", d3.forceManyBody().strength(5))
  .force("center", d3.forceCenter(width / 2, height / 2))
  .force("x", d3.forceX().x(d => xScale(d.category)).strength(0.3))
  .force("y", d3.forceY().y(d => yScale(d.category)).strength(0.3))
  .force("collision", d3.forceCollide().radius(d => radiusScale(d.value) + 1))
  .on("tick", ticked);
```

### Clustering with forceX/forceY
To cluster bubbles by category (e.g., sector), assign x/y targets based on category:
```javascript
// Create cluster centers for each sector
const sectors = [...new Set(data.map(d => d.sector))];
const clusterCenters = {};
const cols = Math.ceil(Math.sqrt(sectors.length));
sectors.forEach((sector, i) => {
  clusterCenters[sector] = {
    x: (i % cols + 0.5) * (width / cols),
    y: (Math.floor(i / cols) + 0.5) * (height / Math.ceil(sectors.length / cols))
  };
});

// Use forceX and forceY
simulation
  .force("x", d3.forceX(d => clusterCenters[d.sector].x).strength(0.3))
  .force("y", d3.forceY(d => clusterCenters[d.sector].y).strength(0.3));
```

### Radius Scale (by market cap)
```javascript
const radiusScale = d3.scaleSqrt()
  .domain([0, d3.max(data, d => d.marketCap)])
  .range([5, 50]);
```

### Color Scale (by sector)
```javascript
const colorScale = d3.scaleOrdinal()
  .domain(sectors)
  .range(d3.schemeTableau10);
```

### forceCollide (prevent overlap)
```javascript
.force("collision", d3.forceCollide()
  .radius(d => radiusScale(d.marketCap) + 2)
  .strength(0.8)
  .iterations(3))
```

### Tick Function
```javascript
function ticked() {
  bubbles
    .attr("cx", d => d.x)
    .attr("cy", d => d.y);
  labels
    .attr("x", d => d.x)
    .attr("y", d => d.y);
}
```

### Tooltip on Hover
```javascript
const tooltip = d3.select("body").append("div")
  .attr("class", "tooltip")
  .style("opacity", 0);

bubbles
  .on("mouseover", (event, d) => {
    tooltip.transition().duration(200).style("opacity", 0.9);
    tooltip.html(`<strong>${d.ticker}</strong><br>${d.name}<br>${d.sector}`)
      .style("left", (event.pageX + 10) + "px")
      .style("top", (event.pageY - 28) + "px");
  })
  .on("mouseout", () => {
    tooltip.transition().duration(500).style("opacity", 0);
  });
```

### Legend
```javascript
const legend = svg.selectAll(".legend")
  .data(sectors)
  .enter().append("g")
  .attr("class", "legend")
  .attr("transform", (d, i) => `translate(0, ${i * 20})`);

legend.append("rect")
  .attr("x", width - 18)
  .attr("width", 18)
  .attr("height", 18)
  .style("fill", d => colorScale(d));

legend.append("text")
  .attr("x", width - 24)
  .attr("y", 9)
  .attr("dy", ".35em")
  .style("text-anchor", "end")
  .text(d => d);
```

## Tips
- Use `d3.scaleSqrt()` for radius to accurately represent area proportional to value
- Use `.strength()` on forceX/forceY (0.2-0.5) to control cluster tightness
- Use `.iterations(3)` on forceCollide for better collision detection
- Set alpha decay to control simulation duration: `.alphaDecay(0.02)`

# D3.js Data Table with Chart Interactivity

## Overview
Creating an interactive HTML data table with D3.js that syncs with chart elements (click to highlight).

## Building a Data Table with D3
```javascript
const table = d3.select("#table-container").append("table");
const thead = table.append("thead");
const tbody = table.append("tbody");

// Header row
thead.append("tr")
  .selectAll("th")
  .data(["Ticker", "Name", "Sector", "Market Cap"])
  .enter()
  .append("th")
  .text(d => d);

// Data rows
const rows = tbody.selectAll("tr")
  .data(data)
  .enter()
  .append("tr")
  .attr("data-ticker", d => d.ticker);

// Cells
rows.selectAll("td")
  .data(d => [d.ticker, d.name, d.sector, formatMarketCap(d.marketCap)])
  .enter()
  .append("td")
  .text(d => d);
```

## Formatting Market Cap
```javascript
function formatMarketCap(value) {
  if (!value) return "N/A";
  if (value >= 1e12) return (value / 1e12).toFixed(2) + "T";
  if (value >= 1e9) return (value / 1e9).toFixed(2) + "B";
  if (value >= 1e6) return (value / 1e6).toFixed(2) + "M";
  return value.toFixed(2);
}
```

## Bidirectional Interactivity

### Bubble click highlights table row
```javascript
bubbles.on("click", (event, d) => {
  // Remove previous highlights
  d3.selectAll("tr").classed("highlighted", false);
  d3.selectAll("circle").classed("selected", false);

  // Highlight the clicked bubble
  d3.select(event.currentTarget).classed("selected", true);

  // Highlight corresponding table row
  const row = d3.select(`tr[data-ticker="${d.ticker}"]`);
  row.classed("highlighted", true);

  // Scroll row into view
  row.node().scrollIntoView({ behavior: "smooth", block: "center" });
});
```

### Table row click highlights bubble
```javascript
rows.on("click", function(event, d) {
  // Remove previous highlights
  d3.selectAll("tr").classed("highlighted", false);
  d3.selectAll("circle").classed("selected", false);

  // Highlight the clicked row
  d3.select(this).classed("highlighted", true);

  // Highlight corresponding bubble
  d3.selectAll("circle")
    .filter(b => b.ticker === d.ticker)
    .classed("selected", true);
});
```

## CSS for Highlighting
```css
tr.highlighted {
  background-color: #fff3cd;
  font-weight: bold;
}

circle.selected {
  stroke: #333;
  stroke-width: 3px;
}
```

## Loading CSV Data with D3
```javascript
// D3 v6 uses promises
Promise.all([
  d3.csv("data/stock-descriptions.csv")
]).then(([stockData]) => {
  // Process data
  stockData.forEach(d => {
    d.marketCap = +d.marketCap || null;
  });
  render(stockData);
});
```

# D3.js CSV Parsing and Number Formatting

## Overview
Handling CSV data loading and number formatting in D3.js v6.

## Loading CSV Files
```javascript
// Single CSV
d3.csv("data/file.csv").then(data => {
  console.log(data); // Array of objects
});

// Multiple CSVs
Promise.all([
  d3.csv("data/descriptions.csv"),
  d3.csv("data/prices.csv")
]).then(([descriptions, prices]) => {
  // Both datasets available
});
```

## CSV Column Access
CSV headers with spaces need bracket notation:
```javascript
data.forEach(d => {
  const name = d["full name"];      // column: "full name"
  const ticker = d.ticker;          // column: "ticker"
  const marketCap = +d.marketCap;   // convert to number with +
});
```

## Number Formatting for Market Cap
```javascript
function formatMarketCap(value) {
  if (value == null || isNaN(value) || value === "") return "N/A";
  const num = +value;
  if (num >= 1e12) return (num / 1e12).toFixed(2) + "T";
  if (num >= 1e9) return (num / 1e9).toFixed(2) + "B";
  if (num >= 1e6) return (num / 1e6).toFixed(2) + "M";
  if (num >= 1e3) return (num / 1e3).toFixed(2) + "K";
  return num.toFixed(2);
}
```

## D3 Number Formatting
```javascript
const formatSI = d3.format(".2s"); // e.g., 1.6T
const formatComma = d3.format(","); // e.g., 1,641,026,945,024
```

## Handling Missing Data
ETF entries may have empty marketCap, country, website fields:
```javascript
data.forEach(d => {
  d.marketCap = d.marketCap ? +d.marketCap : null;
  d.isETF = d.sector === "ETF";
});
```

# Responsive Side-by-Side Layout for D3 Visualizations

## Overview
Creating a responsive side-by-side layout with a chart on one side and a data table on the other.

## HTML Structure
```html
<div class="container">
  <div class="chart-panel" id="bubble-chart"></div>
  <div class="table-panel" id="data-table"></div>
</div>
```

## CSS Flexbox Layout
```css
.container {
  display: flex;
  flex-direction: row;
  gap: 20px;
  padding: 20px;
  height: calc(100vh - 40px);
}

.chart-panel {
  flex: 1;
  min-width: 0;
}

.table-panel {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
}
```

## Scrollable Table
```css
.table-panel {
  overflow-y: auto;
  max-height: calc(100vh - 80px);
}

table {
  width: 100%;
  border-collapse: collapse;
}

th, td {
  padding: 8px 12px;
  text-align: left;
  border-bottom: 1px solid #ddd;
}

th {
  position: sticky;
  top: 0;
  background: #f8f9fa;
  z-index: 1;
}
```

## SVG Responsive Sizing
```javascript
const svg = d3.select("#bubble-chart")
  .append("svg")
  .attr("width", "100%")
  .attr("height", "100%")
  .attr("viewBox", `0 0 ${width} ${height}`);
```

# D3.js Tooltip and Legend Patterns

## Tooltip Implementation
```javascript
// Create tooltip div
const tooltip = d3.select("body").append("div")
  .attr("class", "tooltip")
  .style("position", "absolute")
  .style("opacity", 0)
  .style("pointer-events", "none");

// Style
/* CSS */
.tooltip {
  background: rgba(0, 0, 0, 0.85);
  color: white;
  padding: 10px 14px;
  border-radius: 6px;
  font-size: 13px;
  line-height: 1.5;
  pointer-events: none;
  box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

// Event handlers
element
  .on("mouseover", (event, d) => {
    if (d.sector === "ETF") return; // Skip ETFs
    tooltip.transition().duration(200).style("opacity", 1);
    tooltip.html(`
      <strong>${d.ticker}</strong><br>
      ${d["full name"]}<br>
      Sector: ${d.sector}
    `)
    .style("left", (event.pageX + 15) + "px")
    .style("top", (event.pageY - 10) + "px");
  })
  .on("mousemove", (event) => {
    tooltip
      .style("left", (event.pageX + 15) + "px")
      .style("top", (event.pageY - 10) + "px");
  })
  .on("mouseout", () => {
    tooltip.transition().duration(300).style("opacity", 0);
  });
```

## Legend for Color Categories
```javascript
const legendGroup = svg.append("g")
  .attr("class", "legend")
  .attr("transform", `translate(${margin.left}, ${height - legendHeight})`);

const legendItems = legendGroup.selectAll(".legend-item")
  .data(categories)
  .enter().append("g")
  .attr("class", "legend-item")
  .attr("transform", (d, i) => `translate(${(i % cols) * itemWidth}, ${Math.floor(i / cols) * 22})`);

legendItems.append("rect")
  .attr("width", 14)
  .attr("height", 14)
  .attr("rx", 3)
  .attr("fill", d => colorScale(d));

legendItems.append("text")
  .attr("x", 20)
  .attr("y", 11)
  .style("font-size", "12px")
  .text(d => d);
```

## Conditional Tooltip (skip ETFs)
```javascript
.on("mouseover", (event, d) => {
  // ETFs have no marketCap, country, or website - skip tooltip
  if (d.sector === "ETF") return;
  // Show tooltip for non-ETF stocks
})
```

