(function () {
  "use strict";

  // ---------- helpers ----------
  function formatMarketCap(value) {
    if (value == null || isNaN(value) || value === "") return "N/A";
    var num = +value;
    if (num >= 1e12) return (num / 1e12).toFixed(2) + "T";
    if (num >= 1e9) return (num / 1e9).toFixed(2) + "B";
    if (num >= 1e6) return (num / 1e6).toFixed(2) + "M";
    if (num >= 1e3) return (num / 1e3).toFixed(2) + "K";
    return num.toFixed(2);
  }

  // ---------- load data ----------
  d3.csv("data/stock-descriptions.csv").then(function (raw) {
    var data = raw.map(function (d) {
      return {
        ticker: d.ticker,
        name: d["full name"],
        sector: d.sector,
        marketCap: d.marketCap ? +d.marketCap : null,
        country: d.country || null,
        website: d.website || null,
        isETF: d.sector === "ETF"
      };
    });

    buildBubbleChart(data);
    buildTable(data);
  });

  // ---------- tooltip (shared) ----------
  var tooltip = d3.select("body").append("div").attr("class", "tooltip").style("opacity", 0);

  // ---------- state ----------
  var selectedTicker = null;

  function selectStock(ticker) {
    // deselect if clicking same one again
    if (selectedTicker === ticker) {
      selectedTicker = null;
    } else {
      selectedTicker = ticker;
    }
    // update bubble highlight
    d3.selectAll("circle.bubble")
      .classed("selected", function (d) { return d.ticker === selectedTicker; });
    // update table highlight
    d3.selectAll("#data-table tbody tr")
      .classed("highlighted", function (d) { return d.ticker === selectedTicker; });
    // scroll table row into view
    if (selectedTicker) {
      var row = d3.select('#data-table tbody tr[data-ticker="' + selectedTicker + '"]');
      if (!row.empty()) {
        row.node().scrollIntoView({ behavior: "smooth", block: "center" });
      }
    }
  }

  // ======================================
  //  BUBBLE CHART
  // ======================================
  function buildBubbleChart(data) {
    var container = d3.select("#bubble-chart");
    var rect = container.node().getBoundingClientRect();
    var width = rect.width - 24;    // account for padding
    var height = rect.height - 50;  // leave room for heading

    var legendHeight = 60;
    var chartHeight = height - legendHeight;

    var svg = container.append("svg")
      .attr("width", width)
      .attr("height", height);

    var chartG = svg.append("g");

    // ---- sectors & colors ----
    var sectors = Array.from(new Set(data.map(function (d) { return d.sector; })));
    var colorScale = d3.scaleOrdinal()
      .domain(sectors)
      .range(d3.schemeTableau10);

    // ---- radius scale ----
    var maxCap = d3.max(data, function (d) { return d.marketCap; });
    var radiusScale = d3.scaleSqrt()
      .domain([0, maxCap])
      .range([8, 52]);

    var etfRadius = 14; // uniform size for ETFs

    function getRadius(d) {
      return d.isETF ? etfRadius : radiusScale(d.marketCap || 0);
    }

    // ---- cluster centers ----
    // Arrange sector clusters in a grid centred in the chart area
    var cols = Math.ceil(Math.sqrt(sectors.length));
    var rows = Math.ceil(sectors.length / cols);
    var cellW = width / (cols + 1);
    var cellH = chartHeight / (rows + 1);

    var clusterCenters = {};
    sectors.forEach(function (s, i) {
      clusterCenters[s] = {
        x: (i % cols + 1) * cellW,
        y: (Math.floor(i / cols) + 1) * cellH
      };
    });

    // ---- force simulation ----
    var simulation = d3.forceSimulation(data)
      .force("x", d3.forceX(function (d) { return clusterCenters[d.sector].x; }).strength(0.35))
      .force("y", d3.forceY(function (d) { return clusterCenters[d.sector].y; }).strength(0.35))
      .force("charge", d3.forceManyBody().strength(2))
      .force("collision", d3.forceCollide()
        .radius(function (d) { return getRadius(d) + 2; })
        .strength(0.9)
        .iterations(4))
      .alphaDecay(0.02)
      .on("tick", ticked);

    // ---- draw bubbles ----
    var bubbles = chartG.selectAll("circle.bubble")
      .data(data)
      .enter()
      .append("circle")
      .attr("class", "bubble")
      .attr("r", function (d) { return getRadius(d); })
      .attr("fill", function (d) { return colorScale(d.sector); })
      .on("mouseover", function (event, d) {
        if (d.isETF) return;
        tooltip.transition().duration(150).style("opacity", 1);
        tooltip.html(
          "<strong>" + d.ticker + "</strong><br>" +
          d.name + "<br>" +
          "Sector: " + d.sector
        )
          .style("left", (event.pageX + 14) + "px")
          .style("top", (event.pageY - 12) + "px");
      })
      .on("mousemove", function (event) {
        tooltip
          .style("left", (event.pageX + 14) + "px")
          .style("top", (event.pageY - 12) + "px");
      })
      .on("mouseout", function () {
        tooltip.transition().duration(250).style("opacity", 0);
      })
      .on("click", function (event, d) {
        selectStock(d.ticker);
      });

    // ---- labels inside bubbles ----
    var labels = chartG.selectAll("text.bubble-label")
      .data(data)
      .enter()
      .append("text")
      .attr("class", "bubble-label")
      .text(function (d) { return d.ticker; })
      .style("font-size", function (d) {
        var r = getRadius(d);
        var len = d.ticker.length;
        var size = Math.min(r * 1.1, r * 2.2 / len + 2);
        return Math.max(7, Math.min(size, 14)) + "px";
      });

    function ticked() {
      bubbles
        .attr("cx", function (d) { return d.x; })
        .attr("cy", function (d) { return d.y; });
      labels
        .attr("x", function (d) { return d.x; })
        .attr("y", function (d) { return d.y; });
    }

    // ---- legend ----
    var legendG = svg.append("g")
      .attr("class", "legend-group")
      .attr("transform", "translate(10," + (chartHeight + 8) + ")");

    var legendItemWidth = (width - 20) / sectors.length;

    var legendItems = legendG.selectAll(".legend-item")
      .data(sectors)
      .enter()
      .append("g")
      .attr("class", "legend-item")
      .attr("transform", function (d, i) {
        // Lay out in two rows if many sectors
        var cols2 = Math.ceil(sectors.length / 2);
        var col = i % cols2;
        var row2 = Math.floor(i / cols2);
        var itemW = (width - 20) / cols2;
        return "translate(" + (col * itemW) + "," + (row2 * 22) + ")";
      });

    legendItems.append("rect")
      .attr("width", 13)
      .attr("height", 13)
      .attr("rx", 3)
      .attr("fill", function (d) { return colorScale(d); });

    legendItems.append("text")
      .attr("x", 18)
      .attr("y", 11)
      .text(function (d) { return d; });
  }

  // ======================================
  //  DATA TABLE
  // ======================================
  function buildTable(data) {
    var container = d3.select("#data-table");

    var wrapper = container.append("div").attr("class", "table-wrapper");
    var table = wrapper.append("table");

    // header
    var columns = [
      { key: "ticker", label: "Ticker Symbol" },
      { key: "name", label: "Full Company Name" },
      { key: "sector", label: "Sector" },
      { key: "marketCap", label: "Market Cap" }
    ];

    table.append("thead").append("tr")
      .selectAll("th")
      .data(columns)
      .enter()
      .append("th")
      .text(function (c) { return c.label; });

    // body
    var rows = table.append("tbody")
      .selectAll("tr")
      .data(data)
      .enter()
      .append("tr")
      .attr("data-ticker", function (d) { return d.ticker; })
      .on("click", function (event, d) {
        selectStock(d.ticker);
      });

    rows.selectAll("td")
      .data(function (d) {
        return columns.map(function (c) {
          if (c.key === "marketCap") return formatMarketCap(d.marketCap);
          return d[c.key];
        });
      })
      .enter()
      .append("td")
      .text(function (v) { return v; })
      .attr("title", function (v) { return v; }); // full text on hover
  }
})();

