      .append("th")
      .text(function (c) { return c.label; });

    // body
    var rows = table.append("tbody")
      .selectAll("tr")
      .data(data)
      .enter()
      .append("tr")
      .attr("data-ticker", function (d) { return d.ticker; })
      .on("click", function (event, d) {
        selectStock(d.ticker);
      });

    rows.selectAll("td")
      .data(function (d) {
        return columns.map(function (c) {
          if (c.key === "marketCap") return formatMarketCap(d.marketCap);
          return d[c.key];
        });
      })
      .enter()
      .append("td")
      .text(function (v) { return v; })
      .attr("title", function (v) { return v; }); // full text on hover
  }
})();
